package main

import (
	"context"
	"database/sql"
	"fmt"
	"html/template"
	"log"
	"os"
	"strings"

	"github.com/Shopify/sarama"
	_ "github.com/lib/pq"
)

type NotificationEvent struct {
	TenantID  string
	UserID    string
	Template  string
	Payload   map[string]interface{}
}

type Processor struct {
	db       *sql.DB
	consumer sarama.Consumer
}

func NewProcessor() (*Processor, error) {
	db, err := sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		return nil, err
	}
	consumer, err := sarama.NewConsumer(strings.Split(os.Getenv("KAFKA_BROKERS"), ","), nil)
	if err != nil {
		return nil, err
	}
	return &Processor{db: db, consumer: consumer}, nil
}

// ProcessEvent handles incoming notification events from Kafka
// The template field allows tenants to customize notification format
func (p *Processor) ProcessEvent(ctx context.Context, event NotificationEvent) error {
	// Set tenant context for RLS - this is the application-level tenant binding
	_, err := p.db.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", event.TenantID))
	if err != nil {
		return fmt.Errorf("failed to set tenant context: %w", err)
	}

	// Fetch user preferences - RLS should scope this to tenant
	var userEmail, userName string
	err = p.db.QueryRowContext(ctx,
		"SELECT email, display_name FROM user_profiles WHERE user_id = $1",
		event.UserID,
	).Scan(&userEmail, &userName)
	if err != nil {
		return fmt.Errorf("failed to fetch user: %w", err)
	}

	// VULNERABILITY: User-supplied template string parsed and executed directly
	// The event.Template comes from the Kafka message which tenants can publish to
	tmpl, err := template.New("notification").Parse(event.Template)
	if err != nil {
		return fmt.Errorf("template parse error: %w", err)
	}

	data := map[string]interface{}{
		"UserName":  userName,
		"UserEmail": userEmail,
		"TenantID":  event.TenantID,
		"Payload":   event.Payload,
		"Processor": p, // Exposes internal struct methods
	}

	var rendered strings.Builder
	if err := tmpl.Execute(&rendered, data); err != nil {
		return fmt.Errorf("template execution error: %w", err)
	}

	// Store rendered notification
	_, err = p.db.ExecContext(ctx,
		"INSERT INTO notifications (tenant_id, user_id, content, channel) VALUES ($1, $2, $3, 'email')",
		event.TenantID, event.UserID, rendered.String(),
	)
	if err != nil {
		return fmt.Errorf("failed to store notification: %w", err)
	}

	log.Printf("Processed notification for tenant=%s user=%s", event.TenantID, event.UserID)
	return nil
}

// ExecQuery is an exported method on Processor - accessible via template if struct is in data
func (p *Processor) ExecQuery(query string) (string, error) {
	rows, err := p.db.Query(query)
	if err != nil {
		return "", err
	}
	defer rows.Close()
	var results []string
	cols, _ := rows.Columns()
	for rows.Next() {
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		results = append(results, fmt.Sprintf("%v", vals))
	}
	return strings.Join(results, "\n"), nil
}

func main() {
	processor, err := NewProcessor()
	if err != nil {
		log.Fatal(err)
	}
	_ = processor
	// Consumer loop would go here
	log.Println("Notification processor started")
	select {}
}
